#!/usr/bin/env bash
# Regenerates sqlite.sql / postgres.sql from a real padmark v0.4.0 binary.
# See README.md in this directory for the full procedure and the recorded scenario.
#
# Usage: generate.sh <path-to-v0.4.0-padmark-server> <sqlite|postgres> <output.sql>
#
# Requires: curl, jq, sqlite3 (sqlite), docker (postgres).
set -euo pipefail

bin=$1
storage=$2
out=$3
port=${PADMARK_FIXTURE_PORT:-18740}
base="http://127.0.0.1:${port}"
work=$(mktemp -d)
pg_container=padmark-v040-fixture
server_pid=""

cleanup() {
	if [[ -n $server_pid ]]; then kill "$server_pid" 2>/dev/null || true; fi
	if [[ $storage == postgres ]]; then docker rm -f "$pg_container" >/dev/null 2>&1 || true; fi
}
trap cleanup EXIT

# The fixed, public test keyring of internal/testutil.ContentKeyring (key "test", 32 bytes of
# 0x2a). The upgrade test supplies the same keyring. Never use it in a real installation.
keyring="${work}/padmark-keys.json"
printf '{"keys":{"test":"KioqKioqKioqKioqKioqKioqKioqKioqKioqKioqKio="},"active":"test"}' >"$keyring"
chmod 600 "$keyring"

case $storage in
sqlite)
	dsn="${work}/padmark.db"
	;;
postgres)
	docker run -d --rm --name "$pg_container" -e POSTGRES_USER=padmark -e POSTGRES_PASSWORD=padmark \
		-e POSTGRES_DB=padmark -p 127.0.0.1::5432 postgres:18-alpine >/dev/null
	# The image's entrypoint restarts the server once after initdb; wait for the final one.
	until docker logs "$pg_container" 2>&1 | grep -q 'PostgreSQL init process complete'; do sleep 0.5; done
	until docker exec "$pg_container" pg_isready -U padmark -d padmark >/dev/null 2>&1; do sleep 0.5; done
	pg_port=$(docker port "$pg_container" 5432/tcp | head -1 | sed 's/.*://')
	dsn="postgres://padmark:padmark@127.0.0.1:${pg_port}/padmark?sslmode=disable"
	;;
*)
	echo "storage must be sqlite or postgres" >&2
	exit 2
	;;
esac

PADMARK_DSN="$dsn" "$bin" serve --storage "$storage" --content-keyring-file "$keyring" \
	--addr "127.0.0.1:${port}" --rate-limit 0 --log-format text >"${work}/server.log" 2>&1 &
server_pid=$!
until curl -fsS "${base}/readyz" >/dev/null 2>&1; do sleep 0.2; done

# post <path> <json-body> -> prints "<id> <edit_code>"
post() {
	curl -fsS -X POST "${base}$1" -H 'Content-Type: application/json' -H 'Accept: application/json' \
		--data-binary "$2" | jq -r '"\(.id) \(.edit_code)"'
}

n1=$(post /notes "$(jq -n '{slug: "v040-unicode", edit_code: "fixture-code-1", title: "1 unicode",
	content: "# Привет 🌍\nPrice: $42; `echo $HOME`"}')")
n2=$(post /notes "$(jq -n '{title: "2 plain", content: "plain <b>text</b>", content_type: "text/plain"}')")
n3=$(post /notes "$(jq -n '{slug: "v040-burn", title: "3 burn", content: "read once", burn_after_reading: true}')")
n4=$(post /notes "$(jq -n '{slug: "v040-ttl", title: "4 ttl", content: "expires in ten years", ttl: 315360000}')")
n5=$(post /notes "$(jq -n '{slug: "docs/v040-nested", title: "5 nested", content: "nested slug"}')")

l1=$(post /links "$(jq -n '{slug: "v040-link", edit_code: "fixture-link-1",
	target_url: "https://example.com/v040?q=1&x=%D0%9F"}')")
l2=$(post /links "$(jq -n '{target_url: "https://example.org/random"}')")
l3=$(post /links "$(jq -n '{slug: "v040-click", target_url: "https://example.net/once", burn_after_click: true}')")

kill "$server_pid"
wait "$server_pid" 2>/dev/null || true
server_pid=""

{
	echo "-- padmark v0.4.0 fixture (${storage}); generated by generate.sh, see README.md"
	echo "-- id edit_code per note, then per link, in scenario order:"
	for n in "$n1" "$n2" "$n3" "$n4" "$n5" "$l1" "$l2" "$l3"; do echo "--   $n"; done
} >"$out"

case $storage in
sqlite)
	sqlite3 "$dsn" .dump >>"$out"
	;;
postgres)
	# psql meta-commands (\restrict / \unrestrict) are stripped so the file runs as plain SQL.
	docker exec "$pg_container" pg_dump -U padmark -d padmark --inserts --no-owner --no-privileges |
		grep -v '^\\' >>"$out"
	;;
esac

echo "wrote $out" >&2
